#include <stdio.h>
#include <stdint.h>

/* 8051 tarzi 8 bitlik tasimali toplama: her bayt ayri ayri, CY biti elde */
static uint32_t add32_8bit(uint32_t a, uint32_t b, int *mc)
{
    uint8_t cy = 0, r[4];
    *mc = 1;                                   /* CLR C */
    for (int i = 0; i < 4; i++) {
        uint16_t s = (uint16_t)((a >> (8 * i)) & 0xFF)
                   + (uint16_t)((b >> (8 * i)) & 0xFF) + cy;
        r[i] = (uint8_t)(s & 0xFF);
        cy   = (uint8_t)(s >> 8);
        *mc += 3;                              /* MOV A,dir; ADDC A,dir; MOV dir,A */
    }
    return (uint32_t)r[0] | ((uint32_t)r[1] << 8)
         | ((uint32_t)r[2] << 16) | ((uint32_t)r[3] << 24);
}

int main(void)
{
    uint32_t a = 0x12345678u, b = 0x9ABCDEF0u;
    int mc = 0;
    uint32_t s8 = add32_8bit(a, b, &mc);
    uint32_t s32 = a + b;                      /* tek komut */

    printf("8bit=0x%08X 32bit=0x%08X esit=%d\n", s8, s32, s8 == s32);
    printf("8051 %d MC = %.1f us\n", mc, mc * 1.0);
    printf("M-sinifi 7 cevrim = %.2f ns\n", 7.0 / 72.0 * 1000.0);
    printf("oran = %.1f\n", (mc * 1.0e-6) / (7.0 / 72.0e6));
    return 0;
}

#include <stdio.h>
#include <stdint.h>

#define SRAM_BASE   0x20000000u
#define SRAM_BB     0x22000000u

/* bit-band alias adresi: alias = tabani + (bayt_ofseti * 32) + (bit * 4) */
static uint32_t bitband(uint32_t addr, unsigned bit)
{
    return SRAM_BB + ((addr - SRAM_BASE) * 32u) + (bit * 4u);
}

/* MPU bolge boyutu alani: boyut = 2^(SIZE+1) */
static unsigned mpu_size_field(uint32_t bytes)
{
    unsigned s = 4;                       /* en kucuk bolge 32 bayt */
    while ((1u << (s + 1)) < bytes) s++;
    return s;
}

int main(void)
{
    printf("alias(0x20000200,3) = 0x%08X\n", bitband(0x20000200u, 3));
    printf("alias(0x20000000,0) = 0x%08X\n", bitband(0x20000000u, 0));

    uint32_t sizes[3] = { 32u, 4096u, 65536u };
    for (int i = 0; i < 3; i++) {
        unsigned s = mpu_size_field(sizes[i]);
        printf("%6u bayt -> SIZE=%2u hizalama=%u\n",
               sizes[i], s, (0x20001000u % sizes[i]) == 0u);
    }

    /* hizasiz kelime erisimi: 4'e bolunmeyen adres iki aktarima bolunur */
    uint32_t addrs[3] = { 0x20000000u, 0x20000002u, 0x20000004u };
    int toplam = 0;
    for (int i = 0; i < 3; i++) {
        int t = (addrs[i] % 4u) ? 2 : 1;
        toplam += t;
        printf("0x%08X -> %d aktarim\n", addrs[i], t);
    }
    printf("toplam aktarim = %d\n", toplam);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

/* Kaydedicileri taklit eden degiskenler (gercek adlar ureticiye gore degisir) */
static volatile uint32_t PLLCFG = 0;   /* [7:0]=N  [11:8]=M  [15:12]=P  */
static volatile uint32_t CFGR   = 0;   /* [3:0]=AHB bolucu  [7:4]=APB1  [11:8]=APB2 */

#define HSE_HZ 8000000u

static uint32_t sysclk_hz(void)
{
    uint32_t n = (PLLCFG >> 0) & 0xFFu;
    uint32_t m = (PLLCFG >> 8) & 0x0Fu;
    uint32_t p = (PLLCFG >> 12) & 0x0Fu;
    return (HSE_HZ / m) * n / p;
}

/* APB icin en kucuk uygun bolucu: 1,2,4,8,16 */
static uint32_t fit_div(uint32_t in, uint32_t limit)
{
    uint32_t d = 1;
    while (in / d > limit) d *= 2;
    return d;
}

int main(void)
{
    PLLCFG = (144u << 0) | (4u << 8) | (4u << 12);
    uint32_t sys = sysclk_hz();
    uint32_t hclk = sys / ((CFGR & 0x0Fu) ? (CFGR & 0x0Fu) : 1u);
    printf("SYSCLK=%u Hz  HCLK=%u Hz\n", sys, hclk);

    uint32_t d1 = fit_div(hclk, 36000000u);
    printf("APB1 bolucu=/%u -> %u Hz\n", d1, hclk / d1);

    /* ADC saati 14 MHz'i asmamali */
    uint32_t adcdiv = 2;
    while (hclk / adcdiv > 14000000u) adcdiv += 2;
    printf("ADC bolucu=/%u -> %u Hz\n", adcdiv, hclk / adcdiv);

    /* SysTick 1 ms */
    uint32_t reload = hclk / 1000u - 1u;
    printf("SysTick reload=%u  24bit sigar=%d\n", reload, reload <= 0xFFFFFFu);

    /* 20 ppm kristal: gunluk kayma */
    double d = 20e-6 * 86400.0;
    printf("20 ppm -> %.3f s/gun\n", d);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

#define FLASH_BASE  0x08000000u
#define BOOT_SIZE   (32u * 1024u)
#define SLOT_SIZE   (112u * 1024u)

/* CRC-32 (IEEE 802.3, yansitilmis polinom 0xEDB88320) */
static uint32_t crc32(const uint8_t *p, uint32_t n)
{
    uint32_t crc = 0xFFFFFFFFu;
    for (uint32_t i = 0; i < n; i++) {
        crc ^= p[i];
        for (int k = 0; k < 8; k++)
            crc = (crc >> 1) ^ (0xEDB88320u & (uint32_t)(-(int32_t)(crc & 1u)));
    }
    return crc ^ 0xFFFFFFFFu;
}

int main(void)
{
    uint32_t a = FLASH_BASE + BOOT_SIZE;
    uint32_t b = a + SLOT_SIZE;
    printf("bootloader 0x%08X-0x%08X\n", FLASH_BASE, FLASH_BASE + BOOT_SIZE - 1u);
    printf("slot A     0x%08X-0x%08X\n", a, a + SLOT_SIZE - 1u);
    printf("slot B     0x%08X-0x%08X\n", b, b + SLOT_SIZE - 1u);

    /* vektor tablosu: 16 sistem istisnasi + 82 IRQ */
    uint32_t entries = 16u + 82u;
    uint32_t bytes = entries * 4u;
    uint32_t align = 128u;                 /* mimari alt sinir: 32 kelime */
    while (align < bytes) align <<= 1;
    printf("tablo %u girdi = %u bayt, VTOR hizalamasi %u bayt\n", entries, bytes, align);
    printf("slot A hizali mi: %u\n", (a % align) == 0u);

    /* sayfa sayisi ve indirme suresi */
    printf("2 KiB sayfa -> %u sayfa\n", SLOT_SIZE / 2048u);
    printf("115200 baud 8N1 -> %.3f s\n", (SLOT_SIZE * 10.0) / 115200.0);

    /* goruntu basligindaki CRC dogrulamasi */
    const uint8_t img[4] = { 'O', 'D', '3', '2' };
    uint32_t c = crc32(img, 4u);
    uint32_t beklenen = 0xA91C86DBu;
    printf("CRC=0x%08X gecerli=%d\n", c, c == beklenen);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

#define PRIO_BITS 4u               /* uygulanan oncelik biti sayisi (aileye gore 3 veya 4) */

static volatile uint8_t IPR[8];     /* oncelik kaydedicileri (bayt dizisi) */

/* Oncelik degerini kaydedicinin UST bitlerine kaydirarak yaz */
static void set_prio(unsigned irq, unsigned prio)
{
    IPR[irq] = (uint8_t)(prio << (8u - PRIO_BITS));
}

/* Grup (on alma) ve alt oncelik ayrimi: g grup biti, s = n - g alt bit */
static unsigned group_of(unsigned prio, unsigned g)
{
    return prio >> (PRIO_BITS - g);
}

/* Yeni kesme calisan kesmeyi on alabilir mi? Kucuk deger = yuksek oncelik */
static int preempts(unsigned yeni, unsigned calisan, unsigned g)
{
    return group_of(yeni, g) < group_of(calisan, g);
}

int main(void)
{
    set_prio(0, 0);
    set_prio(1, 5);
    set_prio(2, 15);
    printf("IPR: 0x%02X 0x%02X 0x%02X\n", IPR[0], IPR[1], IPR[2]);

    unsigned g = 2;                 /* 2 grup biti -> 4 on alma, 4 alt seviye */
    printf("g=%u -> %u on alma x %u alt = %u kombinasyon\n",
           g, 1u << g, 1u << (PRIO_BITS - g), 1u << PRIO_BITS);

    unsigned pairs[3][2] = { {1, 5}, {4, 5}, {6, 5} };
    for (int i = 0; i < 3; i++) {
        printf("yeni=%u calisan=%u grup %u/%u onalir=%d\n",
               pairs[i][0], pairs[i][1],
               group_of(pairs[i][0], g), group_of(pairs[i][1], g),
               preempts(pairs[i][0], pairs[i][1], g));
    }

    /* cevrim butcesi */
    int ayri = 12 + 12, kuyruk = 6;
    printf("ayri giris/cikis=%d cevrim, kuyruklama=%d cevrim, kazanc=%d\n",
           ayri, kuyruk, ayri - kuyruk);
    printf("72 MHz'de kazanc = %.1f ns\n", (ayri - kuyruk) / 72.0 * 1000.0);

    int butce = 12 + 6 + 40 + 100;
    printf("en kotu gecikme = %d cevrim = %.3f us\n", butce, butce / 72.0);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

/* CFSR alanlari: MMFSR [7:0], BFSR [15:8], UFSR [31:16] */
#define MM_DACCVIOL   (1u << 1)
#define MM_MSTKERR    (1u << 4)
#define MM_MMARVALID  (1u << 7)
#define BF_PRECISERR  (1u << 9)
#define BF_IMPRECISERR (1u << 10)
#define BF_BFARVALID  (1u << 15)
#define UF_INVSTATE   (1u << 17)
#define UF_UNALIGNED  (1u << 24)
#define UF_DIVBYZERO  (1u << 25)

static void decode(uint32_t cfsr, uint32_t bfar, uint32_t mmfar)
{
    printf("CFSR=0x%08X MMFSR=0x%02X BFSR=0x%02X UFSR=0x%04X\n",
           cfsr, cfsr & 0xFFu, (cfsr >> 8) & 0xFFu, (cfsr >> 16) & 0xFFFFu);
    if (cfsr & MM_DACCVIOL)    printf("  MemManage: veri erisim ihlali\n");
    if (cfsr & MM_MSTKERR)     printf("  MemManage: yigitlama hatasi\n");
    if (cfsr & MM_MMARVALID)   printf("  MMFAR gecerli: 0x%08X\n", mmfar);
    if (cfsr & BF_PRECISERR)   printf("  BusFault: kesin (precise)\n");
    if (cfsr & BF_IMPRECISERR) printf("  BusFault: kesin degil (imprecise)\n");
    if (cfsr & BF_BFARVALID)   printf("  BFAR gecerli: 0x%08X\n", bfar);
    if (cfsr & UF_INVSTATE)    printf("  UsageFault: gecersiz durum (Thumb biti 0)\n");
    if (cfsr & UF_UNALIGNED)   printf("  UsageFault: hizasiz erisim\n");
    if (cfsr & UF_DIVBYZERO)   printf("  UsageFault: sifira bolme\n");
}

int main(void)
{
    /* 1) NULL isaretciye yazma: kesin veri yolu hatasi, BFAR = 0 */
    decode(BF_PRECISERR | BF_BFARVALID, 0x00000000u, 0u);

    /* 2) Thumb biti 0 olan bir fonksiyon isaretcisine atlama */
    decode(UF_INVSTATE, 0u, 0u);

    /* 3) MPU bekci bolgesine tasan yigit */
    decode(MM_DACCVIOL | MM_MMARVALID, 0u, 0x2000F000u);

    /* Yigitlanmis cerceve: R0,R1,R2,R3,R12,LR,PC,xPSR */
    uint32_t frame[8] = { 1u, 2u, 3u, 4u, 0xCCCCCCCCu,
                          0x08001235u, 0x080004A8u, 0x61000000u };
    uint32_t lr = 0xFFFFFFFDu;
    printf("yigit: %s\n", (lr & 4u) ? "PSP" : "MSP");
    printf("hatali PC = 0x%08X (ofset %u bayt)\n", frame[6], (unsigned)(6u * 4u));
    printf("donus LR  = 0x%08X\n", frame[5]);
    printf("xPSR      = 0x%08X\n", frame[7]);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

#define BUF   256u                  /* dairesel tampon: ornek sayisi */
#define CH      8u                  /* tarama kanali */
#define SPS  80000u                 /* toplam ornek/s = 8 kanal x 10 kHz */
#define FCPU 72000000u

static uint16_t buf[BUF];
static volatile uint32_t NDTR;       /* DMA'nin kalan aktarim sayaci */

/* DMA yazma konumu: dairesel kipte NDTR geriye sayar */
static uint32_t dma_index(void) { return BUF - NDTR; }

/* Yarim/tam aktarim kesmesinde islenecek yarinin baslangici */
static uint32_t half_start(int ust_yari) { return ust_yari ? BUF / 2u : 0u; }

int main(void)
{
    for (uint32_t i = 0; i < BUF; i++) buf[i] = (uint16_t)(i * 3u);

    NDTR = 128u;                     /* yarisi doldu */
    printf("NDTR=%u -> yazma indeksi=%u\n", NDTR, dma_index());
    printf("alt yari [%u..%u], ust yari [%u..%u]\n",
           half_start(0), half_start(0) + BUF / 2u - 1u,
           half_start(1), half_start(1) + BUF / 2u - 1u);

    /* alt yarinin ilk kanal degerlerinin toplami */
    uint32_t s = 0;
    for (uint32_t i = half_start(0); i < half_start(0) + BUF / 2u; i += CH) s += buf[i];
    printf("alt yari kanal0 toplami=%u adet=%u\n", s, (BUF / 2u) / CH);

    /* zamanlama */
    double half_ms = (BUF / 2.0) / SPS * 1000.0;
    printf("yari aktarim periyodu=%.2f ms\n", half_ms);

    /* bant genisligi: her aktarim 1 okuma + 1 yazma */
    uint32_t dma_cyc = SPS * 2u;
    printf("DMA cevrim/s=%u  veri yolu=%.4f %%\n",
           dma_cyc, 100.0 * dma_cyc / FCPU);

    uint32_t isr_cyc = SPS * (12u + 20u);
    printf("ornek basina ISR cevrim/s=%u  CPU=%.3f %%  oran=%.1f\n",
           isr_cyc, 100.0 * isr_cyc / FCPU, (double)isr_cyc / dma_cyc);

    /* 1024 kelimelik bellek-bellek blok */
    printf("blok 1024 kelime: DMA %.2f us, CPU dongusu %.2f us\n",
           1024.0 * 2 / FCPU * 1e6, 1024.0 * 9 / FCPU * 1e6);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <math.h>

#define FTIM 72000000.0
#define ARR_MAX 65536u

/* PWM icin en kucuk on bolucu + ARR: cozunurlugu en yuksek tutan cozum */
static void pwm_solve(double fpwm, uint32_t *psc, uint32_t *arr)
{
    uint32_t p = 0;
    while (FTIM / (p + 1) / fpwm > (double)ARR_MAX) p++;
    *psc = p;
    *arr = (uint32_t)(FTIM / ((p + 1) * fpwm) + 0.5) - 1u;
}

int main(void)
{
    double fs[3] = { 1000.0, 20000.0, 100000.0 };
    for (int i = 0; i < 3; i++) {
        uint32_t psc, arr;
        pwm_solve(fs[i], &psc, &arr);
        double gercek = FTIM / ((double)(psc + 1) * (arr + 1));
        printf("%6.0f Hz -> PSC=%u ARR=%u adim=%u cozunurluk=%.2f bit gercek=%.2f Hz\n",
               fs[i], psc, arr, arr + 1u, log2((double)arr + 1.0), gercek);
    }

    /* Yakalama ile frekans olcumu: iki yakalama arasindaki fark */
    uint32_t cap[2] = { 1200u, 8400u };
    uint32_t d = cap[1] - cap[0];
    printf("yakalama %u->%u fark=%u -> f=%.1f Hz cozunurluk=%.4f %%\n",
           cap[0], cap[1], d, FTIM / d, 100.0 / d);

    /* 16 bit tasma siniri */
    printf("16 bit tasma=%.2f us -> en dusuk f=%.1f Hz\n",
           ARR_MAX / FTIM * 1e6, FTIM / ARR_MAX);

    /* Olu zaman */
    double dt_ns = 500.0, tick_ns = 1e9 / FTIM;
    printf("olu zaman %.0f ns = %.0f tik (tik=%.3f ns)\n",
           dt_ns, dt_ns / tick_ns, tick_ns);
    printf("20 kHz'de gorev dongusu kaybi = %.2f %%\n", dt_ns * 1e-9 * 20000.0 * 100.0);

    /* Kodlayici x4 */
    uint32_t ppr = 1000u, cpr = ppr * 4u, dcnt = 400u;
    double rps = (double)dcnt / cpr / 0.010;
    printf("x4: %u sayim/tur, 10 ms'de %u sayim -> %.1f tur/s = %.0f rpm\n",
           cpr, dcnt, rps, rps * 60.0);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <math.h>

#define VREF   3.3
#define NBITS  12
#define FADC   12000000.0
#define CHOLD  5e-12
#define RADC   1000.0

/* 12 bit icin gereken en az ornekleme zamani: t >= (Rs+Radc)*C*ln(2^(N+1)) */
static double t_sample_min(double rs)
{
    return (rs + RADC) * CHOLD * log(pow(2.0, NBITS + 1));
}

int main(void)
{
    double lsb = VREF / (1 << NBITS);
    printf("LSB=%.3f uV adim=%d\n", lsb * 1e6, 1 << NBITS);

    /* donusum suresi: ornekleme cevrimi + 12.5 cevrim */
    double ts_cyc = 15.0;
    double tconv = (ts_cyc + 12.5) / FADC;
    printf("tconv=%.4f us -> %.1f kSa/s\n", tconv * 1e6, 1.0 / tconv / 1000.0);
    printf("8 kanal tarama=%.3f us, max cerceve=%.1f kHz\n",
           8 * tconv * 1e6, 1.0 / (8 * tconv) / 1000.0);

    /* kaynak empedansi kisiti */
    double rs[2] = { 1000.0, 10000.0 };
    for (int i = 0; i < 2; i++)
        printf("Rs=%5.0f ohm -> t_s>=%.1f ns = %.2f cevrim\n",
               rs[i], t_sample_min(rs[i]) * 1e9, t_sample_min(rs[i]) * FADC);

    double tsmax = ts_cyc / FADC;
    double rmax = tsmax / (CHOLD * log(pow(2.0, NBITS + 1))) - RADC;
    printf("15 cevrim -> maks Rs=%.0f ohm\n", rmax);

    /* referans hatasinin mutlak dogruluga etkisi */
    double err = 0.005;
    double lsbs = err * (1 << NBITS);
    printf("Vref %%%.1f -> %.2f LSB -> mutlak %.2f bit\n",
           err * 100, lsbs, log2((double)(1 << NBITS) / lsbs));

    /* ENOB ve asiri ornekleme */
    double sinad = 65.0;
    printf("SINAD=%.1f dB -> ENOB=%.2f bit (ideal %.2f dB)\n",
           sinad, (sinad - 1.76) / 6.02, 6.02 * NBITS + 1.76);
    int m = 16;
    printf("M=%d ortalama -> +%.1f bit, ornek hizi x%d\n", m, 0.5 * log2((double)m), m);

    /* DAC */
    int code = 2048;
    printf("DAC kod %d -> %.4f V\n", code, code / 4096.0 * VREF);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

#define APB1 36000000u
#define APB2 72000000u

/* CAN bit zamanlamasi: 1 (sync) + seg1 + seg2 = ntq; tq = (BRP+1)/f_apb */
typedef struct { unsigned brp, seg1, seg2, ntq; double sp; } can_cfg;

static int can_solve(uint32_t fapb, uint32_t bitrate, can_cfg *c)
{
    for (unsigned ntq = 20; ntq >= 8; ntq--) {          /* buyukten kucuge: cozunurluk yuksek olsun */
        uint32_t ftq = bitrate * ntq;
        if (fapb % ftq) continue;                       /* tam bolunmeli */
        unsigned brp = fapb / ftq - 1u;
        unsigned seg2 = 2u;
        unsigned seg1 = ntq - 1u - seg2;
        c->brp = brp; c->seg1 = seg1; c->seg2 = seg2; c->ntq = ntq;
        c->sp = (double)(1u + seg1) / ntq;
        return 1;
    }
    return 0;
}

/* standart CAN cercevesi: 47 bit ek yuk + veri */
static unsigned can_frame_bits(unsigned n) { return 47u + 8u * n; }

int main(void)
{
    can_cfg c;
    if (can_solve(APB1, 500000u, &c))
        printf("CAN: ntq=%u BRP=%u seg1=%u seg2=%u ornekleme=%.2f %%\n",
               c.ntq, c.brp, c.seg1, c.seg2, c.sp * 100.0);

    printf("tq=%.3f ns bit=%.3f us\n",
           1e9 * (c.brp + 1u) / APB1, 1e6 * c.ntq * (c.brp + 1u) / APB1);

    unsigned b = can_frame_bits(8u);
    printf("8 bayt cerceve=%u bit = %.1f us\n", b, b / 500000.0 * 1e6);
    unsigned stuff = (34u + 8u * 8u - 1u) / 4u;
    printf("en kotu doldurma +%u bit = %.1f us\n", stuff, (b + stuff) / 500000.0 * 1e6);

    double tol = 1.0 / (2.0 * 13.0 * c.ntq);
    printf("osilator toleransi <= %.4f %% = %.0f ppm\n", tol * 100.0, tol * 1e6);

    /* SPI: 10 MHz sinirli aygit icin en kucuk uygun bolucu */
    unsigned d = 2;
    while (APB2 / d > 10000000u) d *= 2;
    printf("SPI /%u -> %u Hz, 1024 bayt = %.1f us\n",
           d, APB2 / d, 1024.0 * 8 / (APB2 / d) * 1e6);

    /* UART: bayt basina ISR maliyeti */
    double bps = 921600.0 / 10.0;
    printf("921600 baud: %.0f bayt/s, ISR 32 cevrim -> CPU %.3f %%\n",
           bps, bps * 32.0 / 72e6 * 100.0);
    printf("bosta hat suresi = %.3f us\n", 10.0 / 921600.0 * 1e6);
    return 0;
}

